const main=$('#main'), modal=$('#modal');
function toast(message,error=false){if(modal.open&&error){let box=$('#modal-error');if(!box){box=document.createElement('p');box.id='modal-error';box.className='warning';box.setAttribute('role','alert');$('#modal-body').prepend(box);}box.textContent=message;box.scrollIntoView({block:'nearest'});}clearTimeout(noticeTimeout);$('#notice').textContent=message;$('#notice').className=error?'error':'';noticeTimeout=setTimeout(()=>$('#notice').textContent='',error?12000:5500);}
function persist(next){next.updatedAt=new Date().toISOString();let raw=JSON.stringify(next);try{if(localStorage.getItem(M.KEY)!==storedRaw)throw Error('Os dados mudaram em outra aba. Recarregue antes de salvar.');localStorage.setItem(M.KEY,raw);}catch(e){throw Error('Não foi possível salvar. '+e.message);}storedRaw=raw;state=next;}
function change(fn,message='Registro salvo neste dispositivo.',celebrate=true){
 try{
  const before=achievementSnapshot(state),next=fn();
  if(!Array.isArray(next.achievementsSeen))next.achievementsSeen=[...(state.achievementsSeen||[])];
  const after=achievementSnapshot(next),seen=new Set(next.achievementsSeen),earned=celebrate?after.unlocked.filter(a=>!before.unlockedIds.has(a.id)&&!seen.has(a.id)):[];
  if(earned.length)next.achievementsSeen=[...new Set([...next.achievementsSeen,...earned.map(a=>a.id)])];
  persist(next);render();toast(message);
  if(earned.length)setTimeout(()=>achievementDialog(earned),120);
  return true;
 }catch(e){toast(e.message,true);return false;}
}
function open(html){$('#modal-body').innerHTML=html;modal.showModal();}
function close(){modal.close();$('#modal-body').innerHTML='';}
$('#close-modal').onclick=close;
function download(name,body,type='application/json'){let url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function backup(){download('Metodo-ET-Camile-'+M.day()+'.json',JSON.stringify(state,null,2));}
async function refreshBuild(){
 toast('Verificando a versão mais recente…');
 try{
  if('serviceWorker' in navigator){const regs=await navigator.serviceWorker.getRegistrations();await Promise.all(regs.filter(reg=>reg.scope.includes('/metodo-camile/')).map(reg=>reg.unregister()));}
  if('caches' in window){const keys=await caches.keys();await Promise.all(keys.filter(key=>key.startsWith('studyos-metodo-et-')).map(key=>caches.delete(key)));}
  let onlineBuild=APP_VERSION;
  try{
   const response=await fetch('./index.html?build-check='+Date.now(),{cache:'no-store'});
   const html=await response.text();
   const match=html.match(/<meta\s+name=["']metodo-et-build["']\s+content=["']([^"']+)["']/i);
   if(match?.[1])onlineBuild=match[1];
  }catch{}
  const url=new URL(location.href);
  url.searchParams.set('build',onlineBuild);
  url.searchParams.set('refresh',Date.now().toString());
  location.replace(url.toString());
 }catch(e){toast('Não foi possível forçar a atualização: '+e.message,true);}
}
function subject(id=selected){return state.subjects.find(s=>s.id===id);}
function heading(kicker,title,description,action=''){return `<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function focusActive(){return false;}
function tabs(){
 return `<div class="tabs">${ACTIVE_SUBJECTS.map(id=>`<button class="secondary" data-select="${id}" aria-pressed="${selected===id}">${label(id)}</button>`).join('')}</div>`;
}
function actionsButton(text,act,extra=''){return `<button data-action="${act}" ${extra}>${text}</button>`;}
function archivedStudyOSStates(){return (state.archive||[]).map(a=>a?.payload?.state||a?.payload).filter(src=>Array.isArray(src?.topics));}
function afoVideoLessons(s,u){if(s?.id!=='afo'||!u)return[];let prefix=String(u.title||'').trim()+' — ',found=new Map();for(let src of archivedStudyOSStates())for(let t of src.topics||[]){if(t?.disciplineId!=='afo')continue;let full=String(t.title||'').trim();if(!full.startsWith(prefix))continue;let text=String(t.details||full.slice(prefix.length)).trim();if(!text||/^PDF\s*—/i.test(text))continue;let order=Number(t.order)||999999;if(!found.has(text)||order<found.get(text))found.set(text,order);}for(let e of u.legacy||[]){let full=String(e.title||'').trim();if(!full.startsWith(prefix))continue;let text=full.slice(prefix.length).trim();if(text&&!/^PDF\s*—/i.test(text)&&!found.has(text))found.set(text,999999+found.size);}return [...found.entries()].sort((a,b)=>a[1]-b[1]||a[0].localeCompare(b[0],'pt-BR')).map(([title])=>title);}
function sessionContentField(s,u,selected=''){
 if(s?.id==='dcon'&&u?.id==='dcon-u-2'){
  const blocks=Array.from({length:24},(_,i)=>'Bloco '+String(i+1).padStart(2,'0'));
  return `<label class="full">Bloco do Art. 5º · Estratégia<select name="title" id="session-content">${option('','Selecionar bloco',selected)}${blocks.map(t=>option(t,t,selected)).join('')}</select></label><small class="full">São 24 blocos de videoaulas. Ao registrar o Bloco 24, a teoria do Art. 5º é reconhecida como concluída.</small>`;
 }
 let items=afoVideoLessons(s,u);if(s?.id==='afo'&&u&&items.length)return `<label class="full">Conteúdo estudado / videoaula<select name="title" id="session-content">${option('','Selecionar videoaula',selected)}${items.map(t=>option(t,t,selected)).join('')}</select></label><label class="full">Outro conteúdo (se não estiver na lista)<input name="customTitle" value="${esc(selected&&!items.includes(selected)?selected:'')}" placeholder="Digite somente se não estiver na lista"></label>`;return `<label class="full">Conteúdo estudado (opcional)<input name="title" value="${esc(selected)}" placeholder="Ex.: leitura complementar ou resolução de questões"></label>`;
}
function refreshSessionContent(){let form=$('#session-form');if(!form)return;let s=subject(form.elements.subjectId.value),u=s?.units.find(u=>u.id===form.elements.unitId.value),wrap=$('#session-content-wrap');if(wrap)wrap.innerHTML=sessionContentField(s,u,'');}
function suggestedTheoryDate(u){let dates=(u?.legacy||[]).map(e=>e.date).filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d||'')).sort();return dates.at(-1)||'';}
function currentSubject(){return subject(M.CYCLE[state.cycle.index]);}
function lawState(){return state.legislation;}
function currentLaw(){let l=lawState();return l.queue[Math.min(l.current,l.queue.length-1)]||l.queue[0];}
function lawElapsed(){return lawTimer?lawTimer.elapsed+(lawTimer.running?Date.now()-lawTimer.started:0):0;}
function saveLawTimer(){try{if(lawTimer)localStorage.setItem(M.KEY+':law-timer',JSON.stringify(lawTimer));else localStorage.removeItem(M.KEY+':law-timer');}catch{toast('O cronômetro da legislação está apenas em memória. Registre o tempo antes de fechar a app.',true);}}
function updateLawClock(){let el=$('#law-clock');if(!el)return;let sec=Math.floor(lawElapsed()/1000);el.textContent=[Math.floor(sec/3600),Math.floor(sec/60)%60,sec%60].map(n=>String(n).padStart(2,'0')).join(':');let target=$('#law-target');if(target)target.textContent=sec>=900?'Meta de 15 min desta legislação alcançada.':Math.max(0,900-sec)+' s para 15 min';}
function lawLastRef(normId){let rows=lawState().sessions.filter(x=>x.normId===normId).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));return rows[0]?.endRef||rows[0]?.startRef||'';}
function legislationPage(){
 const l=lawState(),pair=legislationPair(M.day()),todayRows=l.sessions.filter(x=>x.date===M.day()),today=todayRows.reduce((a,x)=>a+x.minutes,0),total=l.sessions.reduce((a,x)=>a+x.minutes,0),rows=[...l.sessions].sort((a,b)=>b.date.localeCompare(a.date)||String(b.createdAt).localeCompare(String(a.createdAt)));
 const cards=pair.map(norm=>{const minutes=todayRows.filter(x=>x.normId===norm.id).reduce((a,x)=>a+x.minutes,0);return `<article class="card law-pair-card"><span class="eyebrow">15 MIN · META DO DIA</span><h2>${esc(norm.short)}</h2><p>${esc(norm.title)}</p><div class="law-pair-time"><strong>${minutes} min</strong><span>/ 15 min</span></div><progress max="15" value="${Math.min(15,minutes)}"></progress><div class="actions"><button class="secondary" data-action="law-pair" data-id="${esc(norm.id)}">Registrar leitura</button></div><small>${lawLastRef(norm.id)?'Retomar de: '+esc(lawLastRef(norm.id)):'Registre onde começou e onde parou.'}</small></article>`;}).join('');
 return heading('30 MINUTOS POR DIA','Legislação Seca · CGU','Dois textos por dia, em alternância. A legislação conta na carga real, mas não movimenta o ciclo principal.')+
 `<div class="grid metrics four"><div class="card metric"><small>HOJE</small><strong>${today} min <span class="muted" style="font-size:16px">/ 30 min</span></strong><progress max="30" value="${Math.min(30,today)}"></progress><span class="sub">${today>=30?'Meta diária concluída.':30-today+' min restantes'}</span></div><div class="card metric"><small>RODÍZIO DE HOJE</small><strong>${esc(pair.map(x=>x.short).join(' + '))}</strong><span class="sub">15 min para cada legislação</span></div><div class="card metric"><small>PRÓXIMO DIA</small><strong>${esc(legislationPair(M.day(new Date(Date.now()+86400000))).map(x=>x.short).join(' + '))}</strong><span class="sub">Alternância automática Dia 1 / Dia 2</span></div><div class="card metric"><small>TOTAL ACUMULADO</small><strong>${M.hm(total)}</strong><span class="sub">Legislação estudada desde o início</span></div></div><div class="grid two">${cards}</div><section class="card section-title"><h2>Regra definida para a Camile</h2><div class="law-plan-lines"><p><b>Dia 1:</b> CF/88 + LAI</p><p><b>Dia 2:</b> Legislação CGU + LGPD</p></div><p class="muted">O rodízio repete automaticamente. A meta é de 30 minutos totais por dia.</p></section><section class="card section-title"><h2>Histórico da Legislação Seca</h2>${rows.length?`<div class="table-wrap"><table><thead><tr><th>DATA</th><th>NORMA</th><th>TEMPO</th><th>LEITURA</th><th>ANOTAÇÃO</th><th>AÇÕES</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(l.queue.find(n=>n.id===x.normId)?.short||x.normId)}</td><td>${x.minutes} min</td><td>${esc([x.startRef,x.endRef].filter(Boolean).join(' → ')||'—')}</td><td>${esc(x.notes||'—')}</td><td><div class="actions"><button class="secondary small" data-action="law-edit" data-id="${esc(x.id)}">Editar</button><button class="secondary small" data-action="law-delete" data-id="${esc(x.id)}">Excluir</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma leitura registrada ainda.</div>'}</section>`;
}
function lawManualDialog(normId,defaultMinutes=15,source='manual'){
 const norm=lawState().queue.find(n=>n.id===normId)||LEGISLATION_QUEUE.find(n=>n.id===normId);
 if(!norm)throw Error('Legislação não encontrada.');
 open(`<h2>Registrar Legislação Seca</h2><p class="muted"><b>${esc(norm.short)}</b> · ${esc(norm.title)}</p><form id="law-form" class="form-grid"><label>Data<input required type="date" name="date" value="${M.day()}" max="${M.day()}"></label><label>Minutos<input required type="number" min="1" max="1440" step="1" name="minutes" value="${defaultMinutes}"></label><label>Ponto inicial<input name="startRef" maxlength="120" placeholder="Ex.: art. 1º"></label><label>Ponto final<input name="endRef" maxlength="120" placeholder="Ex.: art. 12"></label><label class="full">Anotação opcional<textarea name="notes" maxlength="2000" placeholder="Ex.: retomar no art. 13"></textarea></label><button class="full">Salvar leitura</button></form>`);
 $('#law-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),minutes=Number(d.minutes);if(!M.validDay(d.date)||d.date>M.day()||!Number.isInteger(minutes)||minutes<1||minutes>1440){toast('Confira a data e o tempo da leitura.',true);return;}if(change(()=>{let next=M.copy(state);next.legislation.sessions.push({id:M.uid(),normId:norm.id,date:d.date,minutes,startRef:String(d.startRef||'').trim(),endRef:String(d.endRef||'').trim(),notes:String(d.notes||'').trim(),source,createdAt:new Date().toISOString()});return next;},'Leitura de legislação registrada.'))close();};
}
function lawRecord(id){return lawState().sessions.find(x=>x.id===id);}
function editLawDialog(id){let rec=lawRecord(id);if(!rec)throw Error('Registro de legislação não encontrado.');let norm=lawState().queue.find(n=>n.id===rec.normId);open(`<h2>Editar leitura de Legislação Seca</h2><p class="muted"><b>${esc(norm?.short||rec.normId)}</b> · ${esc(norm?.title||'')}</p><form id="law-edit-form" class="form-grid"><label>Data<input required type="date" name="date" value="${esc(rec.date)}" max="${M.day()}"></label><label>Minutos<input required type="number" min="1" max="1440" step="1" name="minutes" value="${rec.minutes}"></label><label>Ponto inicial<input name="startRef" maxlength="120" value="${esc(rec.startRef||'')}" placeholder="Ex.: art. 1º"></label><label>Ponto final<input name="endRef" maxlength="120" value="${esc(rec.endRef||'')}" placeholder="Ex.: art. 12"></label><label class="full">Anotação opcional<textarea name="notes" maxlength="2000">${esc(rec.notes||'')}</textarea></label><button class="full">Salvar alterações</button></form>`);$('#law-edit-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),minutes=Number(d.minutes);if(!M.validDay(d.date)||d.date>M.day()||!Number.isInteger(minutes)||minutes<1||minutes>1440){toast('Confira a data e o tempo da leitura.',true);return;}if(change(()=>{let next=M.copy(state),x=next.legislation.sessions.find(x=>x.id===id);if(!x)throw Error('Registro de legislação não encontrado.');Object.assign(x,{date:d.date,minutes,startRef:String(d.startRef||'').trim(),endRef:String(d.endRef||'').trim(),notes:String(d.notes||'').trim(),updatedAt:new Date().toISOString()});return next;},'Leitura de legislação atualizada.'))close();};}
function deleteLawDialog(id){let rec=lawRecord(id);if(!rec)throw Error('Registro de legislação não encontrado.');let norm=lawState().queue.find(n=>n.id===rec.normId);open(`<h2>Excluir leitura?</h2><div class="warning">Esta ação removerá o registro de <b>${esc(norm?.short||rec.normId)}</b> de ${esc(rec.date)}, com ${rec.minutes} min. Os demais estudos não serão alterados.</div><form id="law-delete-form"><button>Confirmar exclusão</button></form>`);$('#law-delete-form').onsubmit=e=>{e.preventDefault();if(change(()=>{let next=M.copy(state),before=next.legislation.sessions.length;next.legislation.sessions=next.legislation.sessions.filter(x=>x.id!==id);if(next.legislation.sessions.length===before)throw Error('Registro de legislação não encontrado.');return next;},'Leitura de legislação excluída.'))close();};}
function completeLawDialog(){let norm=currentLaw();open(`<h2>Concluir ${esc(norm.short)}</h2><p class="muted">Confirme somente depois de chegar ao final da norma. A próxima da fila será liberada automaticamente.</p><form id="law-complete-form"><button>Concluir norma e avançar</button></form>`);$('#law-complete-form').onsubmit=e=>{e.preventDefault();if(change(()=>{let next=M.copy(state),l=next.legislation,n=l.queue[l.current];if(!l.completed.some(x=>x.normId===n.id))l.completed.push({normId:n.id,date:M.day(),at:new Date().toISOString()});if(l.current<l.queue.length-1)l.current++;return next;},'Norma concluída. Próxima leitura liberada.'))close();};}
