 const nextBlock=next?'<h3>'+esc(next.title)+'</h3><p class="muted">'+esc(next.note)+'</p><div class="actions"><button data-action="bizur-record" data-id="'+esc(next.id)+'">Registrar este módulo</button><a href="#subjects">Ver grade BizurAFO →</a></div>':'<div class="empty">Rota principal concluída. Revise o que ainda estiver nebuloso.</div>';
